"""Decisões humanas após leitura sequencial de Jaeger, Ping, Sudiatmika e Cho."""
import hashlib
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'reports/fechamento_integral_20261029'

def save(name,data):(OUT/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

def main():
    inv=json.loads((OUT/'inventario_unidades.json').read_text(encoding='utf-8'));idx={x['id']:x for x in inv['unidades']}
    sources=json.loads((OUT/'manifesto_fontes.json').read_text(encoding='utf-8'));smap={x['id']:x for x in sources}
    for sid in ['D15','D21','D25']:
        s=smap[sid];assert hashlib.sha256((ROOT/s['arquivo']).read_bytes()).hexdigest()==s['sha256']
        s['estado_leitura']='texto_integral_lido_decisoes_em_andamento'
        s['log_leitura']=[{'paginas_pdf':list(range(1,s['paginas']+1)),'metodo':'Leitura sequencial do texto completo extraído, incluindo referências; blocos exibidos sem truncamento.','visuais_abertos_nesta_etapa':[2,3,4,5] if sid=='D15' else [],'limite':'Texto completo lido não é inspeção visual de todas as páginas nem reprodução de experimentos. Passe de similaridade ainda não concluído.'}]
    proposals=[
      {'unidade':'U0184','fonte':'D21','localizador':'PDF 1–2, aplicações e conclusão','diagnostico':'parcialmente_condizente','afirmacoes':[{'afirmacao':'Previsão de volatilidade pode apoiar decisões e gestão de riscos.','diagnostico':'condizente','localizador':'PDF 1: importance/implications'},{'afirmacao':'A discussão demonstra relevância operacional de prever o fechamento da PETR4 e dificuldade adicional da B3.','diagnostico':'nao_sustentada_pela_fonte','localizador':'Fonte conceitual não estuda B3, PETR4 ou rentabilidade de uma previsão de preços.'}], 'motivo':'Distinguir previsão de volatilidade de previsão de nível de preço; retirar a dificuldade adicional da B3 atribuída sem estudo comparativo.','proposta':'Ping (2023) discute a previsão de volatilidade como apoio à avaliação de riscos, à precificação de opções e à alocação de ativos. Essa discussão trata da incerteza das variações de preços e não comprova a rentabilidade de um modelo de previsão do fechamento. Nesta pesquisa, o objeto é a predição de um passo à frente da PETR4, sob as condições experimentais descritas.'},
      {'unidade':'U0191','fonte':'D25','localizador':'PDF 2–3, seção 2.1; Cho 2014 PDF 2, equação 1','diagnostico':'condizente_com_ajuste_de_precisao','afirmacoes':[{'afirmacao':'RNRs mantêm estado atualizado pela entrada atual e pelo estado anterior.','diagnostico':'condizente','localizador':'Sudiatmika PDF2, RNNs; Cho PDF2, equação1'},{'afirmacao':'A arquitetura, isoladamente, assegura captura de dependências distantes ou prevalência de uso.','diagnostico':'nao_demonstrada_por_esta_passagem','localizador':'Sudiatmika PDF2–3 reconhece desvanecimento em RNNs convencionais; não fornece levantamento de prevalência.'}], 'motivo':'Especificar comparação com redes feedforward e conservar memória temporal sem sugerir garantia de longo alcance ou prevalência quantificada.','proposta':'As Redes Neurais Recorrentes (RNRs) são uma classe de modelos para processar sequências. Sudiatmika e Putra (2024) descrevem um estado interno atualizado a cada passo a partir da entrada atual e do estado anterior. Em contraste com redes feedforward sem estado recorrente, essa organização permite incorporar o histórico da sequência ao cálculo das saídas. A aprendizagem de dependências longas, contudo, permanece condicionada à arquitetura e ao treinamento.'},
      {'unidade':'U0193','fonte':'D25','localizador':'PDF 3–4, seções 2.2–2.4; PDF 7–8, resultados; Cho 2014 PDF 3','diagnostico':'parcialmente_condizente','afirmacoes':[{'afirmacao':'GRU emprega estrutura de portas mais simples que LSTM.','diagnostico':'condizente','localizador':'Cho PDF3, seção2.3; Sudiatmika PDF3'},{'afirmacao':'Maior eficiência em sequências curtas é resultado computacional medido no experimento de Sudiatmika e Putra.','diagnostico':'nao_demonstrada_como_resultado_proprio','localizador':'PDF4 é revisão de outros estudos; PDF7–8 contém MSE, MAE e R², sem comparação de tempos.'}], 'motivo':'Identificar como discussão secundária a eficiência associada a sequências curtas; não convertê-la em medição própria nem confundir número de observações da série com comprimento da sequência.','proposta':'As LSTMs utilizam portas para controlar a preservação, a atualização e o descarte de informação, enquanto as GRUs empregam uma estrutura simplificada de atualização e reinicialização do estado. Na revisão de Sudiatmika e Putra (2024), essa simplificação é associada a possíveis ganhos de eficiência e ao tratamento de sequências mais curtas. Trata-se de discussão de estudos anteriores; o experimento de previsão do ouro apresentado pelos autores compara erros, sem fornecer uma medição de tempo de treinamento.'}
    ]
    for x in proposals:
        u=idx[x['unidade']];x.update(texto_anterior=u['texto'],sha256_texto_base=u['sha256_texto'],estado='proposto_nao_incorporado');assert len(x['proposta'])<=700
        u.update(status_conteudo='reexaminada_correcao_proposta',afirmacoes=x['afirmacoes'])
    checked=[{'unidade':'U0203','referencia':'R28','diagnostico':'condizente','localizador':'Jaeger PDF1–5: estados, ajuste linear, regularização e limites da ESP','afirmacoes':[{'afirmacao':'Reservatório produz estados; saída é ajustada por regressão.','diagnostico':'condizente','localizador':'PDF1–3'},{'afirmacao':'Treinar somente a saída não garante estabilidade numérica ou uma razão universal de tempos.','diagnostico':'condizente_como_delimitacao','localizador':'PDF3–5: condições da ESP, regularização e discussão histórica, sem razão universal de tempos.'}]},
    {'unidade':'U0256','referencia':['R28','R46'],'diagnostico':'condizente','localizador':'Jaeger PDF1–5; Vishwas PDF20–22','afirmacoes':[{'afirmacao':'ESN usual mantém reservatório fixo e ajusta saída, em contraste com treinamento integral por BPTT.','diagnostico':'condizente','localizador':'Jaeger PDF1–3 e5'},{'afirmacao':'Diferença de treinamento pode motivar comparação de custos sem garantia universal.','diagnostico':'condizente_como_interpretacao_delimitada','localizador':'Jaeger PDF4–6 e Vishwas PDF20–22; a proposta de comparação é interpretação do presente trabalho.'}]}]
    for x in checked:idx[x['unidade']].update(status_conteudo='conferida_no_texto_base',afirmacoes=x['afirmacoes'])
    notes={
      'D15':{'P1':'? mantido: nenhum nome de lei ligado a Win/W no texto completo/figuras lidas.','P2':'S mantido: PDF4–5 descreve ajuste conjunto, regularização, validação e experimentação manual.','P3':'? mantido: washout/ruído de estado/controle de escala não são preparação de série bruta documentada.','P4':'? mantido: não há comparação numérica qualificadora com LSTM/GRU/Transformer.','P5':'— mantido: demonstração de gerador de frequência e discussão conceitual, não análise financeira identificada.'},
      'D21':{'P1':'— mantido: não estuda matrizes ESN.','P2':'— mantido: não seleciona hiperparâmetros ESN/RC.','P3':'? mantido: volatilidade histórica e variância não documentam operação aplicada a uma série identificada.','P4':'? mantido: não há comparação quantitativa de arquiteturas.','P5':'? mantido: mercado genérico sem ativo/índice vinculado à análise.'},
      'D25':{'P1':'— mantido: experimento de LSTM/GRU, não ESN/RC.','P2':'— mantido: grid search existe, mas ajusta LSTM/GRU e não satisfaz o objeto P2.','P3':'D mantido: MinMaxScaler e janelas de60dias, PDF4–5.','P4':'D mantido: comparação própria LSTM/GRU com MSE/MAE/R², PDF7–8.','P5':'D mantido: previsão financeira do ouro com dados Yahoo; não individualiza bolsa, ticker ou contrato, que não devem ser inventados.'}}
    save('achados_leituras_lote2.json',{'base':'v005','sha256_base':inv['sha256_base'],'propostas':proposals,'conferidas_sem_mudanca':checked,'revalidacao_celulas':notes,'cho_2014':{'arquivo':'fontes_suplementares/Cho_2014_EMNLP.pdf','url':'https://aclanthology.org/D14-1179/','leitura':'Texto completo das11páginas, incluindo referências, lido sequencialmente. Figura2 e equações de portas ainda exigem inspeção visual nesta meta.','uso':'Confirma RNN com estado e proposta de unidade de duas portas em codificador-decodificador; não é evidência financeira.','metadados':'Título, sete autores, EMNLP2014, Doha, ACL, páginas1724–1734 e DOI conferidos na fonte primária.','nao_encerrado':'O parágrafo que também cita Hochreiter/Schmidhuber depende da leitura dessa outra fonte. Não aprovar automaticamente todas as suas afirmações.'},'limites':'Aprovação de uma oração não aprova todos os itens de parágrafos com fontes/declarações adicionais. Código, números próprios, similaridade e versão final têm passes separados.'})
    save('inventario_unidades.json',inv);save('manifesto_fontes.json',sources)
    state=json.loads((OUT/'estado_meta.json').read_text(encoding='utf-8'));state['fontes_com_texto_integral_lido_nesta_meta']=['D30','D15','D21','D25','SUP_CHO2014'];state['achados_com_correcao_proposta']=6;state['fontes_suplementares_recuperadas_nesta_meta']=['Jaeger2001_errata2010','Cho2014'];save('estado_meta.json',state)
    print('Três propostas e duas unidades conferidas sem mudança; leituras e15células documentadas.')

if __name__=='__main__':main()
